-- Create a function to send email notification for new users
CREATE OR REPLACE FUNCTION notify_new_user()
RETURNS TRIGGER AS $$
DECLARE
  user_email TEXT;
  user_id_text TEXT;
BEGIN
  -- Get the user's email
  user_email := NEW.email;
  user_id_text := NEW.id::TEXT;

  -- Log the new user creation
  RAISE LOG 'New user created: % (ID: %)', user_email, user_id_text;

  -- Insert into a notification queue table (we'll create this)
  INSERT INTO new_user_notifications (user_id, user_email, created_at)
  VALUES (NEW.id, user_email, NOW());

  RETURN NEW;
