import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.80.0';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type'
};

/**
 * Send New User Email Notification Edge Function
 * 
 * This function:
 * 1. Checks for new user notifications that haven't been sent
 * 2. Sends an email to the admin (benny_thomas21@yahoo.co.in)
 * 3. Marks the notification as sent
 * 
 * Can be triggered:
 * - Manually via HTTP request
 * - Via a cron job (recommended: every 5 minutes)
 */

Deno.serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  console.log('=== Send New User Email Function Started ===');
  console.log('Timestamp:', new Date().toISOString());

  try {
    // Validate environment variables
    const supabaseUrl = Deno.env.get('SUPABASE_URL');
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    const resendApiKey = Deno.env.get('RESEND_API_KEY');
    const adminEmail = 'benny_thomas21@yahoo.co.in';

    if (!supabaseUrl || !supabaseServiceKey) {
      console.error('Missing Supabase configuration');
      return new Response(
        JSON.stringify({ error: 'Server configuration error: Supabase credentials missing' }),
        {
          status: 500,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        }
      );
    }

    // Initialize Supabase client
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false
      }
    });

    // Fetch unsent notifications
    console.log('Fetching unsent notifications...');
    const { data: notifications, error: fetchError } = await supabase
      .from('new_user_notifications')
      .select('*')
      .eq('notification_sent', false)
      .order('created_at', { ascending: true })
      .limit(10);

    if (fetchError) {
      console.error('Error fetching notifications:', fetchError);
      return new Response(
        JSON.stringify({
          error: 'Failed to fetch notifications',
          details: fetchError.message
        }),
        {
          status: 500,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        }
      );
    }

    if (!notifications || notifications.length === 0) {
      console.log('No unsent notifications found');
      return new Response(
        JSON.stringify({
          success: true,
          message: 'No new user notifications to send',
          count: 0
        }),
        {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        }
      );
    }

    console.log(`Found ${notifications.length} unsent notifications`);

    let sentCount = 0;
    let failedCount = 0;

    // Process each notification
    for (const notification of notifications) {
      try {
        console.log(`Processing notification for user: ${notification.user_email}`);

        // Format the email content
        const emailSubject = `New User Signup: ${notification.user_email}`;
        const emailBody = `
          <h2>New User Signup Notification</h2>
          <p>A new user has signed up for Recall:</p>
          <ul>
            <li><strong>Email:</strong> ${notification.user_email}</li>
            <li><strong>User ID:</strong> ${notification.user_id}</li>
            <li><strong>Signup Time:</strong> ${new Date(notification.created_at).toLocaleString()}</li>
          </ul>
          <p>This is an automated notification from your Recall app.</p>
        `;

        // If Resend API key is available, send via Resend
        if (resendApiKey) {
          console.log('Sending email via Resend...');
          const resendResponse = await fetch('https://api.resend.com/emails', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${resendApiKey}`
            },
            body: JSON.stringify({
              from: 'Recall App <onboarding@resend.dev>',
              to: [adminEmail],
              subject: emailSubject,
              html: emailBody
            })
          });

          if (!resendResponse.ok) {
            const errorText = await resendResponse.text();
            console.error('Resend API error:', errorText);
            failedCount++;
            continue;
          }

          console.log('Email sent successfully via Resend');
        } else {
          // Fallback: Just log the notification (no email service configured)
          console.log('No email service configured. Logging notification:');
          console.log('To:', adminEmail);
          console.log('Subject:', emailSubject);
          console.log('Body:', emailBody);
        }

        // Mark notification as sent
        const { error: updateError } = await supabase
          .from('new_user_notifications')
          .update({
            notification_sent: true,
            notified_at: new Date().toISOString()
          })
          .eq('id', notification.id);

        if (updateError) {
          console.error('Error updating notification status:', updateError);
          failedCount++;
        } else {
          sentCount++;
          console.log(`Notification marked as sent for user: ${notification.user_email}`);
        }
      } catch (error) {
        console.error(`Error processing notification for ${notification.user_email}:`, error);
        failedCount++;
      }
    }

    console.log('=== Email sending completed ===');
    console.log(`Sent: ${sentCount}, Failed: ${failedCount}`);

    return new Response(
      JSON.stringify({
        success: true,
        message: 'New user notifications processed',
        sent: sentCount,
        failed: failedCount,
        total: notifications.length
      }),
      {
        status: 200,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      }
    );
  } catch (error) {
    console.error('=== Error in Send New User Email Function ===');
    console.error('Error type:', error?.constructor?.name);
    console.error('Error message:', error instanceof Error ? error.message : 'Unknown error');
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack trace');

    return new Response(
      JSON.stringify({
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error'
      }),
      {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      }
    );
  }
});

