-- Create trigger function to call embedding-recall edge function
CREATE OR REPLACE FUNCTION trigger_recall_embedding_processing()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  request_id bigint;
  payload text;
BEGIN
  -- Construct the JSON payload as text
  payload := json_build_object(
    'recall_id', NEW.id::text,
    'text', COALESCE(NEW.text, ''),
    'location', COALESCE(NEW.location, ''),
    'location_primary_type', COALESCE(NEW.location_primary_type, '')
  )::text;

  -- Call the embedding-recall edge function
  -- The service role key should be configured in Supabase settings
  SELECT INTO request_id supabase_functions.http_request(
    'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/embedding-recall',
    'POST',
    '{"Content-Type":"application/json"}'::jsonb,
    payload::jsonb,
    '10000'
  );

  -- Log success
  RAISE LOG 'Recall embedding processing triggered for recall % with request_id %', NEW.id, request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the insert/update
    RAISE WARNING 'Failed to trigger recall embedding processing for recall %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
    RETURN NEW;
END;
$$;

-- Create trigger that fires AFTER INSERT OR UPDATE on recalls table
-- This ensures the data has been saved before the edge function runs
DROP TRIGGER IF EXISTS trigger_embedding_on_recall_save ON recalls;

CREATE TRIGGER trigger_embedding_on_recall_save
  AFTER INSERT OR UPDATE OF text, location, location_primary_type ON recalls
  FOR EACH ROW
  EXECUTE FUNCTION trigger_recall_embedding_processing();

-- Add comment to explain the trigger
COMMENT ON TRIGGER trigger_embedding_on_recall_save ON recalls IS 
  'Automatically triggers the embedding-recall edge function whenever a recall is inserted or updated. The trigger fires AFTER the data is saved to ensure data consistency.';

-- Enable the trigger that was disabled
ALTER TABLE recalls ENABLE TRIGGER trigger_embedding_on_recall_save;

-- Verify the trigger is now enabled
DO $$
DECLARE
  trigger_status char(1);
BEGIN
  SELECT tgenabled INTO trigger_status
  FROM pg_trigger
  WHERE tgname = 'trigger_embedding_on_recall_save';

  IF trigger_status = 'O' THEN
    RAISE EXCEPTION 'Trigger is still disabled';
  ELSIF trigger_status = 'D' THEN
    RAISE EXCEPTION 'Trigger is disabled';
  ELSE
    RAISE NOTICE 'Trigger is now enabled (status: %)', trigger_status;
  END IF;
END $$;

-- Drop the existing trigger
DROP TRIGGER IF EXISTS trigger_embedding_on_recall_save ON recalls;

-- Recreate the trigger (it will be enabled by default)
CREATE TRIGGER trigger_embedding_on_recall_save
  AFTER INSERT OR UPDATE OF text, location, location_primary_type ON recalls
  FOR EACH ROW
  EXECUTE FUNCTION trigger_recall_embedding_processing();

-- Verify the trigger is enabled
DO $$
DECLARE
  trigger_status char(1);
  trigger_count int;
BEGIN
  SELECT COUNT(*) INTO trigger_count
  FROM pg_trigger
  WHERE tgname = 'trigger_embedding_on_recall_save';

  IF trigger_count = 0 THEN
    RAISE EXCEPTION 'Trigger was not created';
  END IF;

  SELECT tgenabled INTO trigger_status
  FROM pg_trigger
  WHERE tgname = 'trigger_embedding_on_recall_save';

  RAISE NOTICE 'Trigger created with status: % (O=disabled, D=disabled, anything else=enabled)', trigger_status;

  IF trigger_status IN ('O', 'D') THEN
    RAISE EXCEPTION 'Trigger is disabled (status: %)', trigger_status;
  END IF;
END $$;

-- Enable the trigger in ALWAYS mode so it fires even during replication
ALTER TABLE recalls ENABLE ALWAYS TRIGGER trigger_embedding_on_recall_save;

-- Verify the trigger is now enabled
DO $$
DECLARE
  trigger_status char(1);
BEGIN
  SELECT tgenabled INTO trigger_status
  FROM pg_trigger
  WHERE tgname = 'trigger_embedding_on_recall_save';

  RAISE NOTICE 'Trigger status: % (A=Always enabled, O=Origin disabled, D=Disabled)', trigger_status;

  IF trigger_status NOT IN ('A', 'O') AND trigger_status IS NOT NULL THEN
    RAISE NOTICE 'Trigger is enabled!';
  ELSIF trigger_status = 'A' THEN
    RAISE NOTICE 'Trigger is enabled in ALWAYS mode (will fire during replication too)';
  ELSE
    RAISE WARNING 'Trigger may still be disabled (status: %)', trigger_status;
  END IF;
END $$;

