        } as ResponseBody),
        {
          status: 500,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        }
      );
    }

    // Get the HTML content
    const html = await response.text();
    console.log('HTML content fetched, length:', html.length);

    // Extract text from HTML
    const extractedText = extractTextFromHtml(html);
    console.log('Text extracted, length:', extractedText.length);

    if (!extractedText || extractedText.length === 0) {
      console.warn('No text content extracted from URL');
      return new Response(
        JSON.stringify({ 
          success: false, 
          error: 'No text content found at URL' 
        } as ResponseBody),
        {
          status: 200,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        }
      );
    }

    console.log('=== Process URL Function Completed Successfully ===');
    return new Response(
      JSON.stringify({ 
        success: true, 
        text: extractedText 
      } as ResponseBody),
      {
        status: 200,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': '*',
        },
      }
    );
  } catch (error) {
    console.error('=== Process URL Function Error ===');
    console.error('Error:', error);

    return new Response(
      JSON.stringify({ 
