import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from 'jsr:@supabase/supabase-js@2';

/**
 * Process URL Edge Function
 * 
 * This function extracts text content from a given URL using a simple HTML parser.
 * It's designed to run asynchronously and return the extracted text.
 * After extracting the text, it updates the recall_urls table with the extracted content.
 * 
 * Input: { url: string, recall_url_id?: string }
 * Output: { success: boolean, text?: string, error?: string }
 */

interface RequestBody {
  url: string;
  recall_url_id?: string;
}

interface ResponseBody {
  success: boolean;
  text?: string;
  error?: string;
}

// Simple HTML tag stripper function
function stripHtmlTags(html: string): string {
  // Remove script and style tags and their content
  let text = html.replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, '');
  text = text.replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, '');

  // Remove HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode common HTML entities
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  text = text.replace(/&apos;/g, "'");

  // Remove extra whitespace
  text = text.replace(/\s+/g, ' ');
  text = text.trim();

  return text;
}

// Extract meaningful text from HTML
function extractTextFromHtml(html: string): string {
  try {
    // Strip all HTML tags
    const text = stripHtmlTags(html);

    // Limit to first 10000 characters to avoid excessive data
    const limitedText = text.substring(0, 10000);

    return limitedText;
  } catch (error) {
    console.error('Error extracting text from HTML:', error);
    return '';
  }
}

Deno.serve(async (req: Request) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
      },
    });
  }

  try {
    console.log('=== Process URL Function Started ===');

    // Parse request body
    const body: RequestBody = await req.json();
    const { url, recall_url_id } = body;

    if (!url) {
      console.error('No URL provided');
      return new Response(
        JSON.stringify({ 
          success: false, 
          error: 'URL is required' 
        } as ResponseBody),
        {
          status: 400,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        }
      );
    }

    console.log('Processing URL:', url);
    if (recall_url_id) {
      console.log('Recall URL ID:', recall_url_id);
    }

    // Validate URL format
    let validUrl: URL;
    try {
      validUrl = new URL(url);
    } catch (error) {
      console.error('Invalid URL format:', error);
      return new Response(
        JSON.stringify({ 
          success: false, 
          error: 'Invalid URL format' 
        } as ResponseBody),
        {
          status: 400,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        }
      );
    }

    // Fetch the URL content
    console.log('Fetching URL content...');
    const response = await fetch(validUrl.toString(), {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; RecallsBot/1.0)',
      },
      // Set a timeout of 10 seconds
      signal: AbortSignal.timeout(10000),
    });

    if (!response.ok) {
      console.error('Failed to fetch URL:', response.status, response.statusText);

      // Update database with error if recall_url_id is provided
      if (recall_url_id) {
        const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
        const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
        const supabase = createClient(supabaseUrl, supabaseServiceKey);

        await supabase
          .from('recall_urls')
          .update({ 
            url_data: `Error: Failed to fetch URL (${response.status} ${response.statusText})` 
          })
          .eq('id', recall_url_id);
      }

      return new Response(
        JSON.stringify({ 
          success: false, 
          error: `Failed to fetch URL: ${response.status} ${response.statusText}` 
        } as ResponseBody),
        {
          status: 500,
