CREATE OR REPLACE FUNCTION public.trigger_process_url()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
DECLARE
  service_role_key TEXT;
  request_id BIGINT;
BEGIN
  -- Get the service role key from vault with the correct name
  SELECT decrypted_secret INTO service_role_key
  FROM vault.decrypted_secrets
  WHERE name = 'SUPABASE_SERVICE_ROLE_KEY'
  LIMIT 1;

  -- Make async HTTP request to process-url edge function
  SELECT net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/process-url',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_role_key
    ),
    body := jsonb_build_object(
      'url', NEW.url,
      'recall_url_id', NEW.id
    )
  ) INTO request_id;

  -- Log the request
  RAISE LOG 'Triggered process-url for recall_url_id: %, request_id: %', NEW.id, request_id;

  RETURN NEW;
END;
$function$;

