    console.log('Location-filtered recall IDs:', recallIds ? `${recallIds.length} IDs` : 'None');

    // Get OpenAI API key
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY');
    if (!openaiApiKey) {
