-- Add RLS policies for recollection_categories to allow users to create and manage their own categories

-- Drop existing policies if any
DROP POLICY IF EXISTS "Authenticated can read categories" ON recollection_categories;

-- Allow users to view their own categories
CREATE POLICY "Users can view their own categories" 
ON recollection_categories 
FOR SELECT 
USING (user_id = auth.uid());

-- Allow users to insert their own categories
CREATE POLICY "Users can insert their own categories" 
ON recollection_categories 
FOR INSERT 
WITH CHECK (user_id = auth.uid());

-- Allow users to update their own categories
CREATE POLICY "Users can update their own categories" 
ON recollection_categories 
FOR UPDATE 
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

-- Allow users to delete their own categories
CREATE POLICY "Users can delete their own categories" 
ON recollection_categories 
FOR DELETE 
USING (user_id = auth.uid());

-- Add a column to track if category matching is in progress
ALTER TABLE recollection_categories 
ADD COLUMN IF NOT EXISTS is_matching BOOLEAN DEFAULT FALSE;

-- Add updated_at column if it doesn't exist
ALTER TABLE recollection_categories 
ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW();

-- Create a trigger to update updated_at on changes
CREATE OR REPLACE FUNCTION update_recollection_categories_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS update_recollection_categories_updated_at_trigger ON recollection_categories;

CREATE TRIGGER update_recollection_categories_updated_at_trigger
BEFORE UPDATE ON recollection_categories
FOR EACH ROW
EXECUTE FUNCTION update_recollection_categories_updated_at();

