import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.80.0';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type'
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const startTime = Date.now();
  console.log('=== Match Recollection Category Function Started ===');

  try {
    const requestBody = await req.json();
    const { recallId, categoryId, mode } = requestBody;

    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY')!;

    if (!supabaseUrl || !supabaseServiceKey || !openaiApiKey) {
      return new Response(JSON.stringify({ error: 'Server configuration error' }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: { autoRefreshToken: false, persistSession: false }
    });

    // Mode 1: Match category against all recalls
    if (mode === 'category' && categoryId) {
      return await matchCategoryAgainstRecalls(supabase, openaiApiKey, categoryId, corsHeaders, startTime);
    }

    // Mode 2: Match recall against all categories
    if (recallId) {
      return await matchRecallAgainstCategories(supabase, openaiApiKey, recallId, corsHeaders, startTime);
    }

    return new Response(JSON.stringify({ error: 'Missing recallId or categoryId' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  } catch (error) {
    console.error('Error:', error);
    return new Response(JSON.stringify({ error: 'Internal server error', details: error.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

async function matchCategoryAgainstRecalls(
  supabase: any,
  openaiApiKey: string,
  categoryId: string,
  corsHeaders: Record<string, string>,
  startTime: number
): Promise<Response> {
  console.log('Matching category against all recalls:', categoryId);

  // Fetch category data
  const { data: categoryData, error: categoryError } = await supabase
    .from('recollection_categories')
    .select('id, category_name, category_search_description, user_id')
    .eq('id', categoryId)
    .single();

  if (categoryError || !categoryData) {
    console.error('Error fetching category:', categoryError);
    return new Response(JSON.stringify({ error: 'Category not found' }), {
      status: 404,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }

  // Fetch all recalls for this user
  const { data: recallsData, error: recallsError } = await supabase
    .from('recalls')
    .select('id, text, location, location_primary_type')
    .eq('user_id', categoryData.user_id);

  if (recallsError || !recallsData || recallsData.length === 0) {
    console.log('No recalls found for user');
    return new Response(JSON.stringify({ success: true, matchCount: 0 }), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }

  console.log(`Found ${recallsData.length} recalls to match against`);

  // Process each recall
  const matches = [];
  for (const recall of recallsData) {
    // Fetch images for this recall
    const { data: imagesData } = await supabase
      .from('recall_images')
      .select('ocr_text, image_explanation')
      .eq('recall_id', recall.id);

    // Build content string
    const textParts = [];
    if (recall.text) textParts.push(`Note: ${recall.text}`);
    if (recall.location) textParts.push(`Location: ${recall.location}`);
    if (recall.location_primary_type) textParts.push(`Type: ${recall.location_primary_type}`);

    if (imagesData) {
      imagesData.forEach((img: any, idx: number) => {
        if (img.ocr_text) textParts.push(`Image ${idx + 1} text: ${img.ocr_text}`);
        if (img.image_explanation) textParts.push(`Image ${idx + 1} description: ${img.image_explanation}`);
      });
    }

    const content = textParts.join('\n');
    if (!content.trim()) continue;

    // Score this recall
    const score = await scoreContent(
      openaiApiKey,
      content,
      categoryData.category_name,
      categoryData.category_search_description
    );

    if (score >= 75) {
      matches.push({ recallId: recall.id, score });
    }
  }

  console.log(`Found ${matches.length} matching recalls`);

  // Delete existing recollections for this category
  await supabase
    .from('recollections')
    .delete()
    .eq('category_id', categoryId)
    .eq('user_id', categoryData.user_id);

  // Insert new matches
  if (matches.length > 0) {
    const recollections = matches.map(m => ({
      recall_id: m.recallId,
      user_id: categoryData.user_id,
      category_id: categoryId,
      match_score: m.score
    }));

    await supabase.from('recollections').insert(recollections);
  }

  const processingTime = Date.now() - startTime;
  return new Response(JSON.stringify({
    success: true,
    matchCount: matches.length,
    processingTimeMs: processingTime
  }), {
    status: 200,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' }
  });
}

