-- Create a function to call the match-recollection-category edge function
CREATE OR REPLACE FUNCTION trigger_match_recollection_category()
RETURNS TRIGGER AS $$
DECLARE
  request_id bigint;
  payload jsonb;
BEGIN
  -- Prepare the payload
  payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'record', row_to_json(NEW),
    'old_record', CASE WHEN TG_OP = 'UPDATE' THEN row_to_json(OLD) ELSE NULL END,
    'recallId', NEW.id
  );

  -- Call the edge function asynchronously using pg_net
  SELECT net.http_post(
    url := current_setting('app.settings.supabase_url') || '/functions/v1/match-recollection-category',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.settings.supabase_service_role_key')
    ),
    body := payload
  ) INTO request_id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger for INSERT on recalls table
DROP TRIGGER IF EXISTS on_recall_insert_match_category ON recalls;
CREATE TRIGGER on_recall_insert_match_category
  AFTER INSERT ON recalls
  FOR EACH ROW
  EXECUTE FUNCTION trigger_match_recollection_category();

-- Create trigger for UPDATE on recalls table
DROP TRIGGER IF EXISTS on_recall_update_match_category ON recalls;
CREATE TRIGGER on_recall_update_match_category
  AFTER UPDATE ON recalls
  FOR EACH ROW
  WHEN (
    -- Only trigger if relevant fields changed
    OLD.text IS DISTINCT FROM NEW.text OR
    OLD.location IS DISTINCT FROM NEW.location OR
    OLD.location_primary_type IS DISTINCT FROM NEW.location_primary_type OR
    OLD.recall_embedding IS DISTINCT FROM NEW.recall_embedding
  )
  EXECUTE FUNCTION trigger_match_recollection_category();

-- Grant necessary permissions
GRANT EXECUTE ON FUNCTION trigger_match_recollection_category() TO postgres, service_role;

-- Set the configuration parameters (these need to be set at runtime)
-- Note: These will be set via ALTER DATABASE or session variables
COMMENT ON FUNCTION trigger_match_recollection_category() IS 
'Triggers the match-recollection-category edge function when a recall is created or updated. 
Requires app.settings.supabase_url and app.settings.supabase_service_role_key to be set.';

