-- Optimize triggers for asynchronous processing
-- This migration makes all edge function triggers truly asynchronous
-- by using pg_net.http_post_async instead of synchronous calls

-- 1. Update OCR trigger to be fully asynchronous
CREATE OR REPLACE FUNCTION public.trigger_ocr_processing()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  request_id bigint;
BEGIN
  -- Use pg_net for async HTTP request (fire and forget)
  -- This doesn't wait for the response, making it truly async
  SELECT INTO request_id net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/ocr-image',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNlc21zZG5ibGtkamtza21pcWliIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MjUwNzU3NywiZXhwIjoyMDc4MDgzNTc3fQ.sda-p3JnahS1cY2LvvpIxH4jrCKxksbiHCoC1F_hRzw'
    ),
    body := jsonb_build_object(
      'record', jsonb_build_object(
        'id', NEW.id::text,
        'recall_id', NEW.recall_id::text,
        'content_type', NEW.content_type,
        'user_id', NEW.user_id::text,
        'cdn_url', COALESCE(NEW.cdn_url, '')
      )
    ),
    timeout_milliseconds := 1000 -- Short timeout since we don't wait for response
  );

  -- Log that we triggered the request (don't wait for completion)
  RAISE LOG 'OCR processing triggered asynchronously for image % with request_id %', NEW.id, request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't fail the insert
    RAISE WARNING 'Failed to trigger OCR processing for image %: % (SQLSTATE: %)', NEW.id, SQLERRM, SQLSTATE;
    RETURN NEW;
END;
$function$;

-- 2. Update people finder trigger to be fully asynchronous
CREATE OR REPLACE FUNCTION public.trigger_people_finder()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
DECLARE
  request_id bigint;
BEGIN
  -- Use pg_net for async HTTP request (fire and forget)
  SELECT INTO request_id net.http_post(
    url := 'https://cesmsdnblkdjkskmiqib.supabase.co/functions/v1/people-finder',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNlc21zZG5ibGtkamtza21pcWliIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MjUwNzU3NywiZXhwIjoyMDc4MDgzNTc3fQ.sda-p3JnahS1cY2LvvpIxH4jrCKxksbiHCoC1F_hRzw'
    ),
    body := jsonb_build_object(
      'recall_id', NEW.id,
      'user_id', NEW.user_id,
      'text', NEW.text
    ),
    timeout_milliseconds := 1000 -- Short timeout since we don't wait for response
  );

  RAISE LOG 'People finder triggered asynchronously for recall % with request_id %', NEW.id, request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to trigger people finder for recall %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$function$;

-- 3. Remove the synchronous category matching trigger on INSERT
-- Category matching will be triggered after OCR completes
DROP TRIGGER IF EXISTS "Match Recollection Category" ON recalls;

-- 4. Keep the logging trigger but make it lightweight
CREATE OR REPLACE FUNCTION public.log_recall_modification()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
  -- Lightweight logging only
  RAISE LOG 'Recall % was % at %', NEW.id, TG_OP, now();
  RETURN NEW;
END;
$function$;

-- 5. Add index on recall_images.recall_id for faster lookups
CREATE INDEX IF NOT EXISTS idx_recall_images_recall_id ON recall_images(recall_id);

-- 6. Add index on recall_people for faster person lookups
CREATE INDEX IF NOT EXISTS idx_recall_people_recall_id ON recall_people(recall_id);
CREATE INDEX IF NOT EXISTS idx_recall_people_person_id ON recall_people(person_id);

-- 7. Add index on persons for faster name lookups
CREATE INDEX IF NOT EXISTS idx_persons_user_id_name ON persons(user_id, person_name);

