    let recallsQuery = supabase.from('recalls').select('id, text, location, location_primary_type, recall_embedding').eq('user_id', user.id).not('recall_embedding', 'is', null);

    if (priorityRecallIds.size > 0) {
      const priorityIds = Array.from(priorityRecallIds);
      imagesQuery = imagesQuery.in('recall_id', priorityIds);
      recallsQuery = recallsQuery.in('id', priorityIds);
    }

    const { data: allImages } = await imagesQuery;
    const { data: allRecalls } = await recallsQuery;

    // Calculate similarity
    const calculateCosineSimilarity = (storedEmbedding: any) => {
      if (!storedEmbedding) return 0;
      let storedArray = storedEmbedding;
      if (typeof storedEmbedding === 'string') {
        try {
          storedArray = storedEmbedding.replace(/[\[\]]/g, '').split(',').map((s: string) => parseFloat(s.trim()));
        } catch { return 0; }
      }
      if (!Array.isArray(storedArray) || storedArray.length !== queryEmbedding.length) return 0;
      let dotProduct = 0, normA = 0, normB = 0;
      for (let i = 0; i < queryEmbedding.length; i++) {
        dotProduct += queryEmbedding[i] * storedArray[i];
        normA += queryEmbedding[i] * queryEmbedding[i];
        normB += storedArray[i] * storedArray[i];
      }
      const denominator = Math.sqrt(normA) * Math.sqrt(normB);
      return denominator === 0 ? 0 : Math.max(-1, Math.min(1, dotProduct / denominator));
    };

    const imageMatches = (allImages || []).map((img: any) => ({
      id: img.id, recall_id: img.recall_id, ocr_text: img.ocr_text || '', image_explanation: img.image_explanation || '',
      similarity: calculateCosineSimilarity(img.recall_image_embedding), source: 'image', isPriority: priorityRecallIds.has(img.recall_id)
    }));

    const recallMatches = (allRecalls || []).map((rec: any) => ({
      id: rec.id, recall_id: rec.id, text: rec.text || '', location: rec.location || '', location_primary_type: rec.location_primary_type || '',
      similarity: calculateCosineSimilarity(rec.recall_embedding), source: 'recall', isPriority: priorityRecallIds.has(rec.id)
    }));

    const allMatches = [...imageMatches, ...recallMatches].filter((m: any) => m.similarity >= 0.40);
    allMatches.sort((a: any, b: any) => (a.isPriority === b.isPriority ? b.similarity - a.similarity : (a.isPriority ? -1 : 1)));

