      if (!existing || match.similarity > existing.similarity) recallMatchMap.set(match.recall_id, match);
    }

    let uniqueMatches = Array.from(recallMatchMap.values()).sort((a: any, b: any) => (a.isPriority === b.isPriority ? b.similarity - a.similarity : (a.isPriority ? -1 : 1)));

    if (uniqueMatches.length === 0) {
      return new Response(JSON.stringify({ answer: null, confidence: 0, results: [], processingTimeMs: Date.now() - startTime, personInfo: personInfo || null }), {
