    });

    if (!qaResponse.ok) {
      return new Response(JSON.stringify({ error: 'Failed to generate answer' }), {
        status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    const qaData = await qaResponse.json();
    const parsed = JSON.parse(qaData.choices?.[0]?.message?.content || '{}');
    const answer = parsed.answer || null;
    const confidence = parsed.confidence || 0;
    const sourcesUsed = parsed.sources || [];

    const sourceRecallIds = sourcesUsed.map((sid: string) => contextWithSources.find((c: any) => c.sourceId === sid)?.recallId).filter((id: string | null) => id);

    const usedRecalls = uniqueMatches.filter((m: any) => sourceRecallIds.includes(m.recall_id)).sort((a: any, b: any) => (a.isPriority === b.isPriority ? b.similarity - a.similarity : (a.isPriority ? -1 : 1)));
    const unusedRecalls = uniqueMatches.filter((m: any) => !sourceRecallIds.includes(m.recall_id)).sort((a: any, b: any) => (a.isPriority === b.isPriority ? b.similarity - a.similarity : (a.isPriority ? -1 : 1)));
    const orderedMatches = [...usedRecalls, ...unusedRecalls];

    const results = orderedMatches.map((m: any) => ({ id: m.recall_id, matchPercentage: Math.round(m.similarity * 100), usedForAnswer: sourceRecallIds.includes(m.recall_id) }));

    return new Response(JSON.stringify({ answer, confidence, results, processingTimeMs: Date.now() - startTime, personInfo: personInfo || null }), {
      status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  } catch (error) {
