    const allRecalls = Array.from(allRecallsMap.values());
    console.log(`Combined ${allRecalls.length} unique recalls from all sources`);

    if (allRecalls.length === 0) {
      console.log('No recalls to process');
      return new Response(JSON.stringify({
        answer: null,
        confidence: 0,
        results: [],
        processingTimeMs: Date.now() - startTime,
        personInfo: personInfo || null,
      }), {
        status: 200,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Get OpenAI API key
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY');
    if (!openaiApiKey) {
      console.error('OPENAI_API_KEY not set');
      return new Response(JSON.stringify({ error: 'OpenAI API key not configured' }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Step 4: Generate answer using OpenAI with ALL recall information
    console.log('Step 4: Generating answer with OpenAI using all recall information...');

    // Sort recalls by priority score first, then match percentage
    allRecalls.sort((a, b) => {
      // First by priority score (location and people get highest priority)
      if (a.priorityScore !== b.priorityScore) {
        return (b.priorityScore || 0) - (a.priorityScore || 0);
      }

      // Then by match percentage
      return (b.matchPercentage || 0) - (a.matchPercentage || 0);
    });

    // Build comprehensive context including all images
    const contextWithSources = allRecalls.map((recall: any, idx: number) => {
      const sourceId = `SOURCE_${idx + 1}`;

      // Build match type indicators with priority markers
      const matchTypes: string[] = [];
      if (recall.isLocationMatch) matchTypes.push('LOCATION ⭐⭐⭐');
      if (recall.isPeopleMatch) matchTypes.push('PEOPLE ⭐⭐⭐');
      if (recall.isKeywordMatch) matchTypes.push('KEYWORD');
      const matchTypeStr = matchTypes.length > 0 ? ` [${matchTypes.join(' + ')}]` : '';

      const tierMarker = recall.tier ? ` [${recall.tier} TIER]` : '';
      const keywordMarker = recall.keywordMatches && recall.totalKeywords 
        ? ` [${recall.keywordMatches}/${recall.totalKeywords} keywords matched]` 
        : '';

      let contextText = `${sourceId} (${Math.round(recall.matchPercentage || 0)}% match${matchTypeStr}${tierMarker}${keywordMarker}):\n`;
      contextText += `Text: ${recall.recall_data?.text || ''}\n`;
      contextText += `Location: ${recall.recall_data?.location || ''}\n`;
      contextText += `Location Type: ${recall.recall_data?.location_primary_type || ''}\n`;

      // Include ALL images with their information
      if (recall.images_data && recall.images_data.length > 0) {
        contextText += `Images (${recall.images_data.length}):\n`;
        recall.images_data.forEach((img: any, imgIdx: number) => {
          contextText += `  Image ${imgIdx + 1} (${Math.round(img.similarity * 100)}% match):\n`;
          if (img.image_explanation) {
            contextText += `    Explanation: ${img.image_explanation}\n`;
          }
          if (img.ocr_text) {
            contextText += `    OCR Text: ${img.ocr_text}\n`;
          }
        });
      }

      return {
        sourceId,
        recallId: recall.recall_id,
        text: contextText,
        matchPercentage: recall.matchPercentage || 0,
        tier: recall.tier || 'MEDIUM',
        isLocationMatch: recall.isLocationMatch || false,
        isPeopleMatch: recall.isPeopleMatch || false,
        isKeywordMatch: recall.isKeywordMatch || false,
        priorityScore: recall.priorityScore || 0
      };
    });

    const context = contextWithSources.map(c => c.text).join('\n');

    const qaPrompt = `You are a search assistant that answers questions thoroughly based on the provided information.

CRITICAL RULES:
- Use information from BOTH the recall text AND all associated images
- If the recalls don't contain enough information to answer the question, say so clearly
- Use bullet points when listing multiple items
- Provide a confidence score (0-100) based on how well the recalls answer the question

MATCH TYPE PRIORITY (VERY IMPORTANT):
- Sources marked with [LOCATION ⭐⭐⭐] or [PEOPLE ⭐⭐⭐] have the HIGHEST PRIORITY and indicate the BEST matches
- These sources should be STRONGLY PREFERRED when generating answers
- Sources with both [LOCATION ⭐⭐⭐ + PEOPLE ⭐⭐⭐] are EXTREMELY relevant
- Sources marked with [KEYWORD] alone have LOWER priority
- Pay attention to TIER markers: [HIGH TIER] (60%+), [MEDIUM TIER] (40-60%), [LOW TIER] (25-40%)
- Pay attention to keyword match counts - more matched keywords indicate better relevance

Question: ${query}

Available Recalls (sorted by priority, with location and people matches at the top):
${context}

Provide your answer in JSON format: {"answer": "your comprehensive answer based on ALL provided information including images", "confidence": 85, "sources": ["SOURCE_1", "SOURCE_2"]}.
If the recalls don't contain the requested information, respond with: {"answer": "I don't have enough information in the provided recalls to answer this question.", "confidence": 0, "sources": []}.`;

    console.log('Making request to OpenAI gpt-4o-mini...');
    const qaResponse = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${openaiApiKey}`
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [
          {
            role: 'user',
            content: qaPrompt
          }
        ],
        temperature: 0.3,
        max_tokens: 500,
        response_format: { type: 'json_object' }
      })
    });

    if (!qaResponse.ok) {
      const errorText = await qaResponse.text();
      console.error('OpenAI QA API error:', errorText);
      return new Response(JSON.stringify({ error: 'Failed to generate answer', details: errorText }), {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    const qaData = await qaResponse.json();
    const qaContent = qaData.choices?.[0]?.message?.content;

    let answer = null;
    let confidence = 0;
    let sourcesUsed: string[] = [];

    if (qaContent) {
      try {
        const parsed = JSON.parse(qaContent);
        answer = parsed.answer || null;
        confidence = parsed.confidence || 0;
        sourcesUsed = parsed.sources || [];
        console.log('Sources used by AI:', sourcesUsed);
      } catch (parseError) {
        console.error('Failed to parse QA response:', parseError);
        answer = qaContent;
        confidence = 50;
      }
    }

    console.log('Answer generated:', answer ? 'Yes' : 'No');
    console.log('Confidence:', confidence);

    // Map source IDs back to recall IDs
    const sourceRecallIds = sourcesUsed
      .map((sourceId: string) => {
        const source = contextWithSources.find(c => c.sourceId === sourceId);
        return source ? source.recallId : null;
      })
      .filter((id: string | null) => id !== null);

    console.log('Recall IDs used for answer:', sourceRecallIds);

    // Create results with proper ordering (priority score first)
    const usedRecalls = allRecalls
      .filter((recall: any) => sourceRecallIds.includes(recall.recall_id))
      .sort((a: any, b: any) => {
        // First by priority score
        if (a.priorityScore !== b.priorityScore) {
          return (b.priorityScore || 0) - (a.priorityScore || 0);
        }

        // Then by match percentage
        return (b.matchPercentage || 0) - (a.matchPercentage || 0);
      });

    const unusedRecalls = allRecalls
      .filter((recall: any) => !sourceRecallIds.includes(recall.recall_id))
      .sort((a: any, b: any) => {
        // First by priority score
        if (a.priorityScore !== b.priorityScore) {
          return (b.priorityScore || 0) - (a.priorityScore || 0);
        }

        // Then by match percentage
        return (b.matchPercentage || 0) - (a.matchPercentage || 0);
      });

    const orderedRecalls = [...usedRecalls, ...unusedRecalls];

    console.log(`Ordered results: ${usedRecalls.length} used for answer, ${unusedRecalls.length} others`);

    // Convert to result format
    const matchResults = orderedRecalls.map((recall: any) => ({
      id: recall.recall_id,
      matchPercentage: Math.round(recall.matchPercentage || 0),
      usedForAnswer: sourceRecallIds.includes(recall.recall_id),
      tier: recall.tier || 'MEDIUM',
      keywordMatches: recall.keywordMatches || 0,
      totalKeywords: recall.totalKeywords || 0,
      isLocationMatch: recall.isLocationMatch || false,
      isPeopleMatch: recall.isPeopleMatch || false,
      isKeywordMatch: recall.isKeywordMatch || false,
      priorityScore: recall.priorityScore || 0
    }));

    const processingTime = Date.now() - startTime;
    console.log('=== Search Recalls V2 completed successfully ===');
    console.log('Total processing time:', processingTime, 'ms');

    return new Response(JSON.stringify({
      answer,
      confidence,
      results: matchResults,
      processingTimeMs: processingTime,
      personInfo: personInfo || null,
    }), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  } catch (error) {
    const processingTime = Date.now() - startTime;
    console.error('=== Error in Search Recalls V2 Edge Function ===');
    console.error('Error type:', error?.constructor?.name);
    console.error('Error message:', error instanceof Error ? error.message : 'Unknown error');
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack trace');
    console.error('Processing time before error:', processingTime, 'ms');

    return new Response(JSON.stringify({
      error: 'Internal server error',
      details: error instanceof Error ? error.message : 'Unknown error',
      processingTimeMs: processingTime
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.80.0';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS'
};

/**
 * Calculate distance between two coordinates using Haversine formula - OPTIMIZED
 */
function calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371; // Earth's radius in kilometers
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

/**
 * Calculate bounding box from center point and buffer distance - OPTIMIZED
 */
function calculateBoundingBox(
  centerLat: number,
  centerLon: number,
  bufferKm: number
): { minLat: number; maxLat: number; minLon: number; maxLon: number } {
  const R = 6371; // Earth's radius in kilometers

  // Calculate latitude bounds
  const latDelta = (bufferKm / R) * (180 / Math.PI);
  const minLat = centerLat - latDelta;
  const maxLat = centerLat + latDelta;

  // Calculate longitude bounds (accounting for latitude)
  const lonDelta = (bufferKm / R) * (180 / Math.PI) / Math.cos(centerLat * Math.PI / 180);
  const minLon = centerLon - lonDelta;
  const maxLon = centerLon + lonDelta;

  return { minLat, maxLat, minLon, maxLon };
}

/**
 * Extract distance from query - OPTIMIZED
 */
function extractDistanceFromQuery(query: string): number | null {
  const distancePattern = /(\d+(?:\.\d+)?)\s*km/i;
  const match = query.match(distancePattern);

  if (match && match[1]) {
    const distance = parseFloat(match[1]);
    if (!isNaN(distance) && distance > 0) {
      return distance;
    }
  }

  return null;
}

/**
 * Use GPT-4o-mini to detect multiple location intents - OPTIMIZED
 */
async function detectMultipleLocationIntents(query: string, openaiApiKey: string) {
  try {
    console.log('Detecting multiple location intents...');

    // Optimized prompt for faster processing with multiple location detection
    const systemPrompt = `Detect ALL location intents in the query. Return JSON array:
[{"hasLocationIntent": true/false, "intentType": "in"|"near"|"near_me"|null, "location": "name"|null, "confidence": 0-100}]

"in [location]" = within area (500m buffer)
"near [location]" = near place (1km radius)
"near me" = user location (1km radius)

Extract ALL locations mentioned. Examples:
- "restaurants in Melbourne and Sydney" → [{"hasLocationIntent": true, "intentType": "in", "location": "Melbourne", "confidence": 95}, {"hasLocationIntent": true, "intentType": "in", "location": "Sydney", "confidence": 95}]
- "near Collingwood or Richmond" → [{"hasLocationIntent": true, "intentType": "near", "location": "Collingwood", "confidence": 90}, {"hasLocationIntent": true, "intentType": "near", "location": "Richmond", "confidence": 90}]
- "near me" → [{"hasLocationIntent": true, "intentType": "near_me", "location": null, "confidence": 100}]

Be precise - only detect explicit location intent.`;

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${openaiApiKey}`,
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: `Analyze: "${query}"` },
        ],
        temperature: 0.1,
        max_tokens: 200, // Increased slightly for multiple locations
      }),
    });

    if (!response.ok) {
      return null;
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content;

    if (!content) {
      return null;
    }

    // Parse JSON response
    let jsonContent = content.trim();
    if (jsonContent.startsWith('```json')) {
      jsonContent = jsonContent.replace(/^```json\n/, '').replace(/\n```$/, '');
    } else if (jsonContent.startsWith('```')) {
      jsonContent = jsonContent.replace(/^```\n/, '').replace(/\n```$/, '');
    }

    const results = JSON.parse(jsonContent);

    // Filter out low confidence results
    const validResults = Array.isArray(results) 
      ? results.filter((r: any) => r.hasLocationIntent && r.confidence >= 70)
      : [];

    if (validResults.length === 0) {
      return null;
    }

    return validResults;
  } catch (error) {
    console.error('Error detecting location intents:', error);
    return null;
  }
}

/**
 * Search for a place using Google Places API - OPTIMIZED
 */
async function searchGooglePlaces(locationQuery: string, googleApiKey: string, userLocation?: { latitude: number; longitude: number }) {
  try {
    console.log('Searching Google Places for:', locationQuery);

    const baseUrl = 'https://places.googleapis.com/v1/places:searchText';

    const requestBody: any = {
      textQuery: locationQuery,
      languageCode: 'en',
      maxResultCount: 1,
    };

    // Add location bias if user location is provided
    if (userLocation) {
      requestBody.locationBias = {
        circle: {
          center: {
            latitude: userLocation.latitude,
            longitude: userLocation.longitude,
          },
          radius: 50000.0, // 50km bias
        },
      };
    }

    const response = await fetch(baseUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': googleApiKey,
        'X-Goog-FieldMask': 'places.id,places.displayName,places.location',
      },
      body: JSON.stringify(requestBody),
    });

    if (!response.ok) {
      return null;
    }

    const data = await response.json();

    if (!data.places || data.places.length === 0) {
      return null;
    }

    const place = data.places[0];
    return {
      placeId: place.id,
      displayName: place.displayName?.text || 'Unknown Place',
      latitude: place.location?.latitude || 0,
      longitude: place.location?.longitude || 0,
    };
  } catch (error) {
    console.error('Error searching Google Places:', error);
    return null;
  }
}

/**
 * Filter recalls by location - OPTIMIZED for O(1) lookup
 */
function filterRecallsByLocation(
  recallsData: any[],
  placeResult: any,
  searchStrategy: string,
  bufferKm: number
): any[] {
  let filteredRecalls: any[];

  if (searchStrategy === 'bounding_box') {
    const bbox = calculateBoundingBox(
      placeResult.latitude,
      placeResult.longitude,
      bufferKm
    );

    // O(n) single pass with early filtering
    filteredRecalls = recallsData
      .filter((recall) => {
        const lat = recall.latitude!;
        const lon = recall.longitude!;
        return (
          lat >= bbox.minLat &&
          lat <= bbox.maxLat &&
          lon >= bbox.minLon &&
          lon <= bbox.maxLon
        );
      })
      .map((recall) => ({
        ...recall,
        distance: calculateDistance(
          placeResult.latitude,
          placeResult.longitude,
          recall.latitude!,
          recall.longitude!
        )
      }))
      .sort((a, b) => a.distance - b.distance);
  } else {
    // O(n) single pass with distance calculation and filtering
    filteredRecalls = recallsData
      .map((recall) => ({
        ...recall,
        distance: calculateDistance(
          placeResult.latitude,
          placeResult.longitude,
          recall.latitude!,
          recall.longitude!
        )
      }))
      .filter((recall) => recall.distance <= bufferKm)
      .sort((a, b) => a.distance - b.distance);
  }

  return filteredRecalls;
}

Deno.serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: corsHeaders,
    });
  }

  const startTime = Date.now();
  console.log('=== search-recalls-with-location started ===');

  try {
    // Get the authorization header
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Missing authorization header' }),
        {
          status: 401,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    // Initialize Supabase client
    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Verify the user's JWT token
    const token = authHeader.replace('Bearer ', '');
    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), {
        status: 401,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // Parse request body
    const { query, userLocation } = await req.json();

    if (!query || typeof query !== 'string' || query.trim().length === 0) {
      return new Response(JSON.stringify({ error: 'Query parameter is required' }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // Get API keys
    const openaiApiKey = Deno.env.get('OPENAI_API_KEY');
    const googleApiKey = Deno.env.get('GOOGLE_PLACES_API_KEY');

    if (!openaiApiKey || !googleApiKey) {
      return new Response(
        JSON.stringify({ error: 'API keys not configured' }),
        {
          status: 500,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    // OPTIMIZATION: Run location intent detection and recall fetching in parallel
    const [locationIntents, recallsResult] = await Promise.all([
      detectMultipleLocationIntents(query, openaiApiKey),
      supabase
        .from('recalls')
        .select('id, latitude, longitude, location, location_primary_type')
        .eq('user_id', user.id)
        .not('latitude', 'is', null)
        .not('longitude', 'is', null)
    ]);

    // If no location intent detected, return early
    if (!locationIntents || locationIntents.length === 0) {
      return new Response(
        JSON.stringify({
          hasLocationIntent: false,
          shouldUseRegularSearch: true,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    if (recallsResult.error) {
      return new Response(
        JSON.stringify({ error: 'Failed to fetch recalls' }),
        {
          status: 500,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    const recallsData = recallsResult.data || [];
    console.log(`Processing ${locationIntents.length} location(s) for ${recallsData.length} recalls`);

    // Process all locations in parallel
    const locationResults = await Promise.all(
      locationIntents.map(async (locationIntent: any) => {
        // Handle "near me" or "around me"
        if (locationIntent.intentType === 'near_me') {
          if (!userLocation || !userLocation.latitude || !userLocation.longitude) {
            return {
              hasLocationIntent: true,
              locationResolved: false,
              error: 'User location required for "near me" queries',
            };
          }

          const extractedDistance = extractDistanceFromQuery(query);
          const radiusKm = extractedDistance !== null ? extractedDistance : 1;

          // Filter recalls by proximity - OPTIMIZED single pass
          const filteredRecalls = recallsData
            .map((recall) => ({
              ...recall,
              distance: calculateDistance(
                userLocation.latitude,
                userLocation.longitude,
                recall.latitude!,
                recall.longitude!
              )
            }))
            .filter((recall) => recall.distance <= radiusKm)
            .sort((a, b) => a.distance - b.distance);

          const recallIds = filteredRecalls.map((r) => r.id);

          return {
            hasLocationIntent: true,
            locationResolved: true,
            recallIds,
            locationInfo: {
              location: 'Your current location',
              resolvedPlace: 'Your current location',
              proximity: radiusKm,
              intentType: 'near_me',
              coordinates: {
                latitude: userLocation.latitude,
                longitude: userLocation.longitude,
              },
            },
          };
        }

        // Resolve location using Google Places API
        const placeResult = await searchGooglePlaces(
          locationIntent.location,
          googleApiKey,
          userLocation
        );

        if (!placeResult) {
          return {
            hasLocationIntent: true,
            locationResolved: false,
            location: locationIntent.location,
          };
        }

        // Determine search strategy
        const searchStrategy = locationIntent.intentType === 'in' ? 'bounding_box' : 'radius';
        const bufferKm = locationIntent.intentType === 'in' ? 0.5 : 1;

        // Filter recalls - OPTIMIZED
        const filteredRecalls = filterRecallsByLocation(
          recallsData,
          placeResult,
          searchStrategy,
          bufferKm
        );

        const recallIds = filteredRecalls.map((r) => r.id);

        return {
          hasLocationIntent: true,
          locationResolved: true,
          recallIds,
          locationInfo: {
            location: locationIntent.location,
            resolvedPlace: placeResult.displayName,
            proximity: bufferKm,
            intentType: locationIntent.intentType,
            searchStrategy,
            coordinates: {
              latitude: placeResult.latitude,
              longitude: placeResult.longitude,
            },
          },
        };
      })
    );

    // Combine results from all locations
    const resolvedLocations = locationResults.filter((r: any) => r.locationResolved);

    if (resolvedLocations.length === 0) {
      return new Response(
        JSON.stringify({
          hasLocationIntent: true,
          locationResolved: false,
          shouldUseRegularSearch: true,
          attemptedLocations: locationIntents.length,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    // Merge recall IDs from all locations (using Set for O(1) deduplication)
    const allRecallIds = new Set<string>();
    resolvedLocations.forEach((result: any) => {
      result.recallIds.forEach((id: string) => allRecallIds.add(id));
    });

    const uniqueRecallIds = Array.from(allRecallIds);

    // Create combined location info
    const locationNames = resolvedLocations
      .map((r: any) => r.locationInfo.resolvedPlace)
      .join(', ');

    const primaryLocation = resolvedLocations[0].locationInfo;

    return new Response(
      JSON.stringify({
        hasLocationIntent: true,
        locationResolved: true,
        recallIds: uniqueRecallIds,
        locationInfo: {
          location: locationNames,
          resolvedPlace: locationNames,
          proximity: primaryLocation.proximity,
          intentType: primaryLocation.intentType,
          searchStrategy: primaryLocation.searchStrategy,
          coordinates: primaryLocation.coordinates,
          multipleLocations: resolvedLocations.length > 1,
          locationCount: resolvedLocations.length,
          locations: resolvedLocations.map((r: any) => r.locationInfo),
        },
        cleanedQuery: query,
        processingTimeMs: Date.now() - startTime,
      }),
      {
        status: 200,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
